type Trie struct {
	kids [26]*Trie
	end  bool
}

func NewTrie() *Trie {
	return &Trie{}
}

func (t *Trie) Insert(word string) {
	node := t
	for i := 0; i < len(word); i++ {
		c := word[i] - 'a'
		if node.kids[c] == nil {
			node.kids[c] = &Trie{}
		}
		node = node.kids[c]
	}
	node.end = true
}

func (t *Trie) node(s string) *Trie {
	node := t
	for i := 0; i < len(s); i++ {
		node = node.kids[s[i]-'a']
		if node == nil {
			return nil
		}
	}
	return node
}

func (t *Trie) Search(word string) bool {
	n := t.node(word)
	return n != nil && n.end
}

func (t *Trie) StartsWith(prefix string) bool {
	return t.node(prefix) != nil
}

