	}
	for _, c := range cases {
		got := maxSlidingWindow(c.nums, c.k)
		if !reflect.DeepEqual(got, c.want) {
			t.Fatalf("maxSlidingWindow(%v, %d) = %v, want %v", c.nums, c.k, got, c.want)
		}
	}
