func TestMaxSlidingWindowMatchesBruteForce(t *testing.T) {
	nums := make([]int, 500)
	x := 7
	for i := range nums {
		x = (x*1103515245 + 12345) % 1000
		nums[i] = x - 500
	}
	for _, k := range []int{1, 2, 7, 60} {
		want := make([]int, 0, len(nums)-k+1)
		for i := 0; i+k <= len(nums); i++ {
			m := nums[i]
			for _, v := range nums[i : i+k] {
				if v > m {
					m = v
				}
			}
			want = append(want, m)
		}
		if got := maxSlidingWindow(nums, k); !reflect.DeepEqual(got, want) {
			t.Fatalf("k=%d disagrees with brute force", k)
		}
	}
}

answer:
func maxSlidingWindow(nums []int, k int) []int {
	if k <= 0 || len(nums) < k {
		return nil
	}
	out := make([]int, 0, len(nums)-k+1)
	dq := make([]int, 0, len(nums))
	for i, v := range nums {
		for len(dq) > 0 && nums[dq[len(dq)-1]] <= v {
			dq = dq[:len(dq)-1]
		}
		dq = append(dq, i)
		if dq[0] <= i-k {
			dq = dq[1:]
		}
		if i >= k-1 {
			out = append(out, nums[dq[0]])
		}
	}
	return out
}
